void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 dx = 1;
    OPJ_UINT32 dy = 1;

    *p_tx0 = (OPJ_INT32)(p_cp->tile_offset_x0[p_tileno]);
    *p_tx1 = (OPJ_INT32)(p_cp->tile_offset_x0[p_tileno] + p_cp->tile_width[p_tileno]);
    *p_ty0 = (OPJ_INT32)(p_cp->tile_offset_y0[p_tileno]);
    *p_ty1 = (OPJ_INT32)(p_cp->tile_offset_y0[p_tileno] + p_cp->tile_height[p_tileno]);

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        const opj_image_comp_t *comp = &p_image->comps[compno];
        for (resno = 0; resno < p_cp->tw + p_cp->th; ++resno) {
            dx = dx * 2;
            dy = dy * 2;
        }

        if (p_dx_min) {
            if (dx < *p_dx_min)
                *p_dx_min = dx;
        }

        if (p_dy_min) {
            if (dy < *p_dy_min)
                *p_dy_min = dy;
        }

        dx = 1;
        dy = 1;
    }

    *p_max_prec = 1;
    *p_max_res = p_cp->tw + p_cp->th;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 i, compno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        for (i = 1; i < p_cp->encoder->tcp->disto_alloc[compno].no_terminations; ++i) {
            if (p_cp->encoder->tcp->disto_alloc[compno].res_spec[i - 1].numres > max_res) {
                max_res = p_cp->encoder->tcp->disto_alloc[compno].res_spec[i - 1].numres;
            }
        }

        for (i = 0; i < p_cp->encoder->tcp->disto_alloc[compno].no_terminations; ++i) {
            if (p_cp->encoder->tcp->disto_alloc[compno].res_spec[i].prec_spec[0].dx < dx_min || dx_min == 0) {
                dx_min = p_cp->encoder->tcp->disto_alloc[compno].res_spec[i].prec_spec[0].dx;
            }
            if (p_cp->encoder->tcp->disto_alloc[compno].res_spec[i].prec_spec[0].dy < dy_min || dy_min == 0) {
                dy_min = p_cp->encoder->tcp->disto_alloc[compno].res_spec[i].prec_spec[0].dy;
            }
            if (p_cp->encoder->tcp->disto_alloc[compno].res_spec[i].no_levels > max_prec) {
                max_prec = p_cp->encoder->tcp->disto_alloc[compno].res_spec[i].no_levels;
            }
        }
    }

    *p_tx0 = (OPJ_INT32)(p_tileno % p_image->x_tile_num) * p_image->tile_width;
    *p_tx1 = *p_tx0 + p_image->tile_width;
    *p_ty0 = (OPJ_INT32)(p_tileno / p_image->x_tile_num) * p_image->tile_height;
    *p_ty1 = *p_ty0 + p_image->tile_height;
    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno, OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1, OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec, OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx_min = p_image->x1 - p_image->x0;
    OPJ_UINT32 dy_min = p_image->y1 - p_image->y0;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        opj_image_comp_t *comp = &p_image->comps[compno];
        opj_tcp_t *tcp = &p_cp->tcp[compno];
        OPJ_UINT32 num_res = tcp->disto_alloc ? tcp->disto_alloc->disto[0].resno + 1 : tcp->numresolutions;

        for (resno = 0; resno < num_res; resno++) {
            OPJ_UINT32 dx = tcp->tx0[resno + 1] - tcp->tx0[resno];
            OPJ_UINT32 dy = tcp->ty0[resno + 1] - tcp->ty0[resno];

            if (dx < dx_min)
                dx_min = dx;

            if (dy < dy_min)
                dy_min = dy;

            if (resno + 1 > max_res)
                max_res = resno + 1;
        }

        if (tcp->precno != OPJ_UINT32_MAX && tcp->precno + 1 > max_prec)
            max_prec = tcp->precno + 1;
    }

    *p_tx0 = p_cp->tx0[p_tileno];
    *p_tx1 = p_cp->tx0[p_tileno + 1];
    *p_ty0 = p_cp->ty0[p_tileno];
    *p_ty1 = p_cp->ty0[p_tileno + 1];
    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno, OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1, OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec, OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 i, j;
    OPJ_UINT32 dx = 0, dy = 0;
    OPJ_UINT32 maxres = 0;
    OPJ_UINT32 maxprec = 0;
    OPJ_UINT32 compno;
    OPJ_UINT32 numcomps = p_image->numcomps;

    for (compno = 0; compno < numcomps; ++compno) {
        OPJ_UINT32 maxres_comp = 0;

        for (i = 0; i < p_cp->tcp->disto_alloc && i < OPJ_DCP_MAX_RES; ++i) {
            OPJ_UINT32 dx_comp = p_cp->tcp->resolutions[i].dx;
            OPJ_UINT32 dy_comp = p_cp->tcp->resolutions[i].dy;

            if (dx_comp > dx) {
                dx = dx_comp;
            }

            if (dy_comp > dy) {
                dy = dy_comp;
            }

            if (i + 1 > maxres_comp) {
                maxres_comp = i + 1;
            }
        }

        if (maxres_comp > maxres) {
            maxres = maxres_comp;
        }

        for (i = 0; i < p_cp->tcp->disto_alloc && i < OPJ_DCP_MAX_RES; ++i) {
            for (j = 0; j < p_cp->tcp->resolutions[i].numprecincts && j < OPJ_DCP_MAX_PRECINCTS; ++j) {
                OPJ_UINT32 dx_prec = p_cp->tcp->resolutions[i].precincts[j].dx;
                OPJ_UINT32 dy_prec = p_cp->tcp->resolutions[i].precincts[j].dy;

                if (dx_prec < dx) {
                    dx = dx_prec;
                }

                if (dy_prec < dy) {
                    dy = dy_prec;
                }

                if (i + 1 > maxprec) {
                    maxprec = i + 1;
                }
            }
        }
    }

    *p_tx0 = (OPJ_INT32)((p_tileno % p_cp->tw) * dx);
    *p_tx1 = *p_tx0 + dx;
    *p_ty0 = (OPJ_INT32)((p_tileno / p_cp->tw) * dy);
    *p_ty1 = *p_ty0 + dy;

    *p_dx_min = dx;
    *p_dy_min = dy;
    *p_max_prec = maxprec;
    *p_max_res = maxres;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 i, compno;
    OPJ_UINT32 maxres = 1;
    OPJ_UINT32 dx, dy;
    OPJ_UINT32 num_resolutions;
    OPJ_UINT32 tile_width = p_image->x1 - p_image->x0;
    OPJ_UINT32 tile_height = p_image->y1 - p_image->y0;
    OPJ_UINT32 num_comps = p_image->numcomps;

    *p_tx0 = (OPJ_INT32)(p_tileno % p_cp->tw) * tile_width;
    *p_tx1 = (*p_tx0) + tile_width;
    *p_ty0 = (OPJ_INT32)(p_tileno / p_cp->th) * tile_height;
    *p_ty1 = (*p_ty0) + tile_height;

    *p_dx_min = 0;
    *p_dy_min = 0;

    for (compno = 0; compno < num_comps; ++compno) {
        num_resolutions = 1;
        dx = 1;
        dy = 1;

        for (i = 1; i < p_cp->tp_on ? p_cp->resolution : 1; ++i) {
            dx = (dx * 2);
            dy = (dy * 2);
        }

        num_resolutions = p_cp->resolution;

        if (num_resolutions > maxres) {
            maxres = num_resolutions;
        }

        if (*p_dx_min == 0 || dx < *p_dx_min) {
            *p_dx_min = dx;
        }

        if (*p_dy_min == 0 || dy < *p_dy_min) {
            *p_dy_min = dy;
        }

        if (num_resolutions > *p_max_prec) {
            *p_max_prec = num_resolutions;
        }
    }

    *p_max_res = maxres;
}
